// Main Process: Receives gesture and controls OS desktop environment
socket.on('gesture', (data) => {
  if (data.gesture === 'SWIPE_LEFT') {
    hudWindow.webContents.send('trigger-ui-animation', 'left');
  } else if (data.gesture === 'PINCH_CLICK') {
    simulateNativeDesktopClick();
  }
});
